// Copyright (c) 2026 Olof Johansson
// SPDX-License-Identifier: BSD-3-Clause

// Host-only tests for App/Browser/ContentProcessRecovery.swift (revision R7).
//
// Run:  make test-policy     (or: scripts/test-content-process-recovery.sh)

import Foundation

var failures = 0
var checks = 0

func expect(_ cond: Bool, _ what: String) {
    checks += 1
    if !cond { failures += 1; print("  FAIL: \(what)") }
}

func section(_ name: String) { print("\n== \(name)") }

let t0 = Date(timeIntervalSinceReferenceDate: 1_000_000)

section("two reloads per sixty seconds, then give up")
var r = ContentProcessRecovery()
expect(r.shouldReload(now: t0), "first termination reloads")
expect(r.shouldReload(now: t0.addingTimeInterval(5)), "second termination within the window reloads")
expect(!r.shouldReload(now: t0.addingTimeInterval(10)), "third within the window gives up (error page)")
expect(!r.shouldReload(now: t0.addingTimeInterval(59)), "still giving up just inside the window")

section("the budget refills as reloads age out")
expect(r.shouldReload(now: t0.addingTimeInterval(60)), "the first reload has aged out at exactly 60 s")
expect(!r.shouldReload(now: t0.addingTimeInterval(61)), "only one slot freed; the 5 s one is still inside")
expect(r.shouldReload(now: t0.addingTimeInterval(65)), "the 5 s reload has aged out too")

section("a refusal does not consume budget")
var q = ContentProcessRecovery()
_ = q.shouldReload(now: t0)
_ = q.shouldReload(now: t0.addingTimeInterval(1))
for i in 2..<20 { _ = q.shouldReload(now: t0.addingTimeInterval(Double(i))) }
expect(q.recentReloads.count == 2, "refused attempts are not recorded as reloads")
expect(q.shouldReload(now: t0.addingTimeInterval(61)), "so the budget refills on schedule, not later")

section("rare terminations always reload")
var rare = ContentProcessRecovery()
var allReloaded = true
for hour in 0..<24 {
    allReloaded = allReloaded && rare.shouldReload(now: t0.addingTimeInterval(Double(hour) * 3600))
}
expect(allReloaded, "one termination an hour, all day: every one reloads")

section("configurable")
var strict = ContentProcessRecovery(maxReloads: 1, window: 10)
expect(strict.shouldReload(now: t0), "one allowed")
expect(!strict.shouldReload(now: t0.addingTimeInterval(9)), "second inside 10 s refused")
expect(strict.shouldReload(now: t0.addingTimeInterval(10)), "allowed again at 10 s")

print("")
if failures == 0 {
    print("\(checks)/\(checks) content process recovery checks passed")
} else {
    print("\(failures) of \(checks) content process recovery checks FAILED")
// Copyright (c) 2026 Olof Johansson
// SPDX-License-Identifier: BSD-3-Clause

//
//  ContentProcessRecovery.swift
//  Latchkey
//
//  When to reload after WebKit's web content process dies (revision R7,
//  finding H10).
//
//  iOS kills a backgrounded app's web content process routinely under memory
//  pressure, and a foreground one occasionally. Upstream turned every
//  termination into a "cannot load from network" error page and never
//  reloaded — so a routine memory kill looked exactly like a tailnet outage,
//  and the dashboard stayed dead until the user found Reload.
//
//  The policy: reload automatically, but not forever. A page that kills its
//  own content process on load (a crash loop, or a page too heavy for the
//  device) would otherwise reload-and-die indefinitely, burning battery and
//  hiding the problem. After `maxReloads` within `window`, stop and show the
//  error page so a human sees it.
//
//  A termination while the app is in the background is not reloaded there:
//  WebKit cannot usefully load in a suspended app, and doing it on return to
//  the foreground puts the page back when it is needed. That deferred reload
//  counts against the same budget.
//
//  Pure Foundation, so `scripts/test-content-process-recovery.sh` compiles it
//  alone.
//

import Foundation

struct ContentProcessRecovery: Sendable {
    /// Reloads allowed within `window` before giving up (R7: 2 per 60 s).
    let maxReloads: Int
    let window: TimeInterval

    /// When recent automatic reloads happened, oldest first, pruned to
    /// `window`.
#!/bin/bash
# Host tests for App/Browser/BrowserViewModel.swift's pure parts: the web
# view configuration every dashboard page is built from (D1: no egress but
# the gateway), and how a navigation error is categorised and described
# (F4's rule: a SOCKS failure is never a "URL format error").
#
# Compiles the REAL view model on the host. It needs WebKit, which macOS
# has; the UIKit-only parts are behind canImport and drop out. TSNetModel,
# AppDiagnostics and the TailscaleKit status types are stubbed to the fields
# the view model reads; everything else it uses is the app's own source.
set -euo pipefail

cd "$(dirname "$0")/.."
OUT=$(mktemp -d)
trap 'rm -rf "$OUT"' EXIT
cp scripts/test-browser-view-model.swift "$OUT/main.swift"
# `import TailscaleKit` is stripped: the stubs provide those types instead.
for f in App/Browser/BrowserViewModel.swift App/Browser/HomePageAvailability.swift TSNet/TailnetProxyPolicy.swift; do
    sed 's/^import TailscaleKit$//' "$f" > "$OUT/$(basename "$f")"
done
# -O and the app's isolation flags, as the other host tests (AGENTS.md).
if ! xcrun swiftc -O -swift-version 6 -strict-concurrency=complete -default-isolation MainActor \
        "$OUT/BrowserViewModel.swift" "$OUT/HomePageAvailability.swift" "$OUT/TailnetProxyPolicy.swift" \
        App/Browser/PageScripts.swift App/Browser/PageScriptSources.swift App/Browser/PopupCatcher.swift \
        App/Browser/GatewayAddress.swift App/Browser/NavigationPolicy.swift \
        App/Browser/TailnetHostnameQualifier.swift App/Browser/ContentProcessRecovery.swift \
        App/Browser/PageState.swift App/Browser/PageFailureText.swift \
        App/Session/SessionManager.swift App/Session/TokenInput.swift App/Session/DashboardSignOut.swift \
        App/Network/SocksRelayPolicy.swift App/Logging/LogRedaction.swift App/TestHooks.swift \
        scripts/test-proxy-policy-stubs.swift scripts/test-socks-relay-stubs.swift \
        scripts/test-browser-view-model-stubs.swift \
        "$OUT/main.swift" -o "$OUT/browser-view-model-tests" > "$OUT/build.log" 2>&1; then
    cat "$OUT/build.log" >&2
    echo "error: the browser view model host tests do not compile" >&2
    exit 1
fi
"$OUT/browser-view-model-tests"

